sql:
SELECT GSoffered
FROM schools
WHERE ABS(Longitude) = (SELECT MAX(ABS(Longitude)) FROM schools);

SELECT account_id
FROM account
WHERE frequency = 'POPLATEK MESICNE';

SELECT atom_id
FROM atom
WHERE molecule_id = 'TR186';

SELECT DISTINCT availability
FROM cards
WHERE artist = 'Daren Bader';

SELECT SUM(CASE WHEN p.publisher_name = 'DC Comics' THEN 1 ELSE 0 END) - SUM(CASE WHEN p.publisher_name = 'Marvel Comics' THEN 1 ELSE 0 END) AS difference
FROM superhero s
JOIN publisher p ON s.publisher_id = p.id;

SELECT team_short_name
FROM Team_Attributes
WHERE buildUpPlayPassing > 70;

SELECT COUNT(*) 
FROM Examination 
WHERE Thrombosis IN (1, 2) AND PT < 14;

SELECT expense_description
FROM expense
WHERE cost > 50;

SELECT CAST(SUM(CASE WHEN Segment = 'Premium' THEN 1 ELSE 0 END) AS REAL) * 100.0 / COUNT(*) 
FROM gasstations 
WHERE Country = 'SVK';
